// Normalize extracted specifications to standard formats
const rawSpecs = $input.item.json;

// Helper function to convert material names to DIN/EN codes
function normalizeMaterial(material) {
  if (!material) return null;

  const materialMap = {
    'aluminum 6061': 'EN AW-6061',
    'aluminium 6061': 'EN AW-6061',
    'al 6061': 'EN AW-6061',
    '6061': 'EN AW-6061',
    'aluminum 7075': 'EN AW-7075',
    'aluminium 7075': 'EN AW-7075',
    'al 7075': 'EN AW-7075',
    '7075': 'EN AW-7075',
    'stainless steel 304': '1.4301',
    'ss 304': '1.4301',
    '304': '1.4301',
    'stainless steel 316': '1.4401',
    'ss 316': '1.4401',
    '316': '1.4401',
    'steel': '1.0037',
    'mild steel': '1.0037',
    'carbon steel': '1.0037'
  };

  const normalized = material.toLowerCase().trim();
  return materialMap[normalized] || material;
}

// Helper function to convert tolerance descriptions to ISO 2768 standards
function normalizeTolerance(tolerance) {
  if (!tolerance) return 'ISO 2768-m'; // default medium

  const toleranceMap = {
    'tight': 'ISO 2768-f',
    'fine': 'ISO 2768-f',
    'high': 'ISO 2768-f',
    'medium': 'ISO 2768-m',
    'standard': 'ISO 2768-m',
    'normal': 'ISO 2768-m',
    'coarse': 'ISO 2768-c',
    'loose': 'ISO 2768-c',
    'very coarse': 'ISO 2768-v'
  };

  const normalized = tolerance.toLowerCase().trim();
  return toleranceMap[normalized] || 'ISO 2768-m';
}

// Helper function to standardize surface finish to Ra values
function normalizeSurfaceFinish(finish) {
  if (!finish) return null;

  const finishMap = {
    'smooth': 'Ra 1.6',
    'polished': 'Ra 0.8',
    'mirror': 'Ra 0.4',
    'rough': 'Ra 6.3',
    'machined': 'Ra 3.2',
    'standard': 'Ra 3.2',
    'as machined': 'Ra 3.2'
  };

  const normalized = finish.toLowerCase().trim();

  // Check if already in Ra format
  if (normalized.includes('ra')) {
    return finish;
  }

  return finishMap[normalized] || 'Ra 3.2';
}

// Helper function to parse quantity as integer
function parseQuantity(qty) {
  if (!qty) return 1;

  if (typeof qty === 'number') return Math.floor(qty);

  const parsed = parseInt(qty.toString().replace(/[^0-9]/g, ''));
  return isNaN(parsed) ? 1 : parsed;
}

// Helper function to parse delivery date to ISO format
function parseDeliveryDate(date) {
  if (!date) return null;

  try {
    const parsedDate = new Date(date);
    if (isNaN(parsedDate.getTime())) return null;
    return parsedDate.toISOString().split('T')[0];
  } catch (e) {
    return null;
  }
}

// Normalize the specifications
const normalized = {
  materialCode: normalizeMaterial(rawSpecs.material),
  dimensions: rawSpecs.dimensions || null,
  toleranceGrade: normalizeTolerance(rawSpecs.tolerance),
  surfaceFinishRa: normalizeSurfaceFinish(rawSpecs.surfaceFinish || rawSpecs.finish),
  quantity: parseQuantity(rawSpecs.quantity || rawSpecs.qty),
  deliveryDate: parseDeliveryDate(rawSpecs.deliveryDate || rawSpecs.delivery),
  rawSpecs: rawSpecs
};

return normalized;

// Score each supplier based on multiple criteria
const suppliers = $input.all();

// Scoring function
const scoreSuppliers = (suppliers) => {
  return suppliers.map(supplier => {
    const data = supplier.json;

    // Capability Match Score (40% weight)
    // Exact material match gets 100%, partial gets 50%
    let capabilityScore = 0;
    if (data.material_match === 'exact') {
      capabilityScore = 100;
    } else if (data.material_match === 'partial') {
      capabilityScore = 50;
    }

    // Capacity Availability Score (30% weight)
    // 100 - current_capacity_percent (lower capacity usage = higher score)
    const capacityScore = 100 - (data.current_capacity_percent || 0);

    // Lead Time Score (20% weight)
    // Inverse of avg_lead_time_days (shorter lead time = higher score)
    const maxLeadTime = 90; // Assume 90 days as max
    const leadTimeScore = data.avg_lead_time_days 
      ? Math.max(0, 100 - (data.avg_lead_time_days / maxLeadTime * 100))
      : 0;

    // Quality History Score (10% weight)
    const qualityScore = data.quality_score || 0;

    // Calculate weighted total score (0-100 scale)
    const totalScore = (
      (capabilityScore * 0.40) +
      (capacityScore * 0.30) +
      (leadTimeScore * 0.20) +
      (qualityScore * 0.10)
    );

    return {
      ...data,
      scores: {
        capability: Math.round(capabilityScore * 100) / 100,
        capacity: Math.round(capacityScore * 100) / 100,
        leadTime: Math.round(leadTimeScore * 100) / 100,
        quality: Math.round(qualityScore * 100) / 100,
        total: Math.round(totalScore * 100) / 100
      },
      totalScore: Math.round(totalScore * 100) / 100
    };
  });
};

// Score all suppliers
const scoredSuppliers = scoreSuppliers(suppliers);

// Sort by total score descending
const sortedSuppliers = scoredSuppliers.sort((a, b) => b.totalScore - a.totalScore);

// Return top 3 suppliers
const top3Suppliers = sortedSuppliers.slice(0, 3);

return top3Suppliers.map(supplier => ({ json: supplier }));

// Get the quote text from the previous node
const quoteText = $('Claude Quote Writer').item.json.response;
const currentDate = new Date().toISOString().split('T')[0];

// Create HTML template for the quote
const htmlContent = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <style>
    body { font-family: Arial, sans-serif; margin: 40px; }
    h1 { color: #333; }
    .quote-content { line-height: 1.6; white-space: pre-wrap; }
    .footer { margin-top: 40px; font-size: 12px; color: #666; }
  </style>
</head>
<body>
  <h1>RFQ Quote</h1>
  <div class="quote-content">${quoteText}</div>
  <div class="footer">Generated on ${currentDate}</div>
</body>
</html>
`;

// Convert HTML to PDF using a library (placeholder for actual PDF generation)
// In a real implementation, you would use a library like puppeteer, pdfkit, or an API service
// For this example, we'll create a simple text-based PDF structure

// Create binary data for the PDF
const filename = `RFQ_Quote_${currentDate}.pdf`;

// Note: This is a simplified example. In production, you would use:
// - An HTTP Request node to call a PDF generation API (like PDFShift, HTML2PDF API)
// - Or install a PDF library in your n8n instance
// - Or use puppeteer if available in your n8n environment

const binaryData = Buffer.from(htmlContent).toString('base64');

return [
  {
    json: {
      filename: filename,
      mimeType: 'application/pdf',
      generatedDate: currentDate,
      quoteText: quoteText
    },
    binary: {
      quote_pdf: {
        data: binaryData,
        mimeType: 'application/pdf',
        fileName: filename,
        fileExtension: 'pdf'
      }
    }
  }
];

// Calculate RFQ complexity score based on multiple factors
const specs = $input.item.json;

// Initialize scoring components
let toleranceScore = 0;
let surfaceFinishScore = 0;
let materialScore = 0;
let quantityScore = 0;
let dimensionScore = 0;

// 1. Tolerance Grade Score (0-25 points)
// Tighter tolerances = higher complexity
const toleranceGrade = specs.toleranceGrade || 'ISO 2768-m';
if (toleranceGrade.includes('2768-f') || toleranceGrade.includes('fine')) {
  toleranceScore = 25;
} else if (toleranceGrade.includes('2768-m') || toleranceGrade.includes('medium')) {
  toleranceScore = 15;
} else if (toleranceGrade.includes('2768-c') || toleranceGrade.includes('coarse')) {
  toleranceScore = 5;
} else if (toleranceGrade.includes('2768-v') || toleranceGrade.includes('very coarse')) {
  toleranceScore = 0;
} else {
  // Check for specific tolerance values (e.g., ±0.01mm)
  const toleranceMatch = toleranceGrade.match(/[±]?\s*0\.(\d+)/);
  if (toleranceMatch) {
    const decimals = toleranceMatch[1].length;
    toleranceScore = Math.min(25, decimals * 8); // More decimal places = tighter tolerance
  } else {
    toleranceScore = 10; // Default medium
  }
}

// 2. Surface Finish Score (0-20 points)
// Lower Ra values = higher complexity (more finishing work)
const surfaceFinish = specs.surfaceFinishRa || 'Ra 3.2';
const raMatch = surfaceFinish.match(/Ra\s*([0-9.]+)/);
if (raMatch) {
  const raValue = parseFloat(raMatch[1]);
  if (raValue <= 0.4) {
    surfaceFinishScore = 20; // Mirror finish
  } else if (raValue <= 0.8) {
    surfaceFinishScore = 18; // Polished
  } else if (raValue <= 1.6) {
    surfaceFinishScore = 15; // Smooth
  } else if (raValue <= 3.2) {
    surfaceFinishScore = 10; // Standard machined
  } else if (raValue <= 6.3) {
    surfaceFinishScore = 5; // Rough machined
  } else {
    surfaceFinishScore = 0; // Very rough
  }
} else {
  surfaceFinishScore = 10; // Default
}

// 3. Material Score (0-25 points)
// Exotic/difficult materials = higher complexity
const materialCode = specs.materialCode || '';
const materialLower = materialCode.toLowerCase();
if (materialLower.includes('titanium') || materialLower.includes('inconel') || materialLower.includes('hastelloy')) {
  materialScore = 25; // Exotic materials
} else if (materialLower.includes('7075') || materialLower.includes('316') || materialLower.includes('1.4401')) {
  materialScore = 20; // High-grade materials
} else if (materialLower.includes('6061') || materialLower.includes('304') || materialLower.includes('1.4301')) {
  materialScore = 12; // Common engineering materials
} else if (materialLower.includes('aluminum') || materialLower.includes('aluminium') || materialLower.includes('brass')) {
  materialScore = 8; // Easy to machine
} else if (materialLower.includes('steel') || materialLower.includes('1.0037')) {
  materialScore = 10; // Standard steel
} else {
  materialScore = 10; // Default
}

// 4. Quantity Score (0-15 points)
// Lower quantities (prototypes) = higher complexity due to setup costs
const quantity = specs.quantity || 1;
if (quantity === 1) {
  quantityScore = 15; // Single prototype
} else if (quantity <= 5) {
  quantityScore = 12; // Very small batch
} else if (quantity <= 25) {
  quantityScore = 8; // Small batch
} else if (quantity <= 100) {
  quantityScore = 4; // Medium batch
} else {
  quantityScore = 0; // Large production run
}

// 5. Dimension Complexity Score (0-15 points)
// Multiple features, complex geometry = higher complexity
const dimensions = specs.dimensions || '';
const dimensionStr = typeof dimensions === 'string' ? dimensions : JSON.stringify(dimensions);

// Count complexity indicators
let complexityIndicators = 0;
if (dimensionStr.match(/thread|tapped|M\d+/i)) complexityIndicators++; // Threading
if (dimensionStr.match(/hole|drill|bore/i)) complexityIndicators++; // Holes
if (dimensionStr.match(/radius|fillet|chamfer/i)) complexityIndicators++; // Edge features
if (dimensionStr.match(/groove|slot|pocket/i)) complexityIndicators++; // Pockets/grooves
if (dimensionStr.match(/angle|degree|°/i)) complexityIndicators++; // Angled features
if (dimensionStr.match(/counterbore|countersink/i)) complexityIndicators++; // Advanced hole features

dimensionScore = Math.min(15, complexityIndicators * 3);

// Calculate total complexity score (0-100)
const totalScore = toleranceScore + surfaceFinishScore + materialScore + quantityScore + dimensionScore;

// Categorize complexity
let category = '';
let recommendedAction = '';
if (totalScore >= 75) {
  category = 'Complex';
  recommendedAction = 'Requires engineering review and detailed cost analysis';
} else if (totalScore >= 50) {
  category = 'Medium';
  recommendedAction = 'Standard processing with supplier verification';
} else {
  category = 'Simple';
  recommendedAction = 'Fast-track processing with automated quoting';
}

// Return enriched data with complexity analysis
return {
  ...specs,
  complexity: {
    totalScore: Math.round(totalScore),
    category: category,
    recommendedAction: recommendedAction,
    breakdown: {
      tolerance: Math.round(toleranceScore),
      surfaceFinish: Math.round(surfaceFinishScore),
      material: Math.round(materialScore),
      quantity: Math.round(quantityScore),
      dimensions: Math.round(dimensionScore)
    },
    factors: {
      toleranceGrade: toleranceGrade,
      surfaceFinish: surfaceFinish,
      materialCode: materialCode,
      quantity: quantity,
      dimensionComplexityIndicators: complexityIndicators
    }
  }
};

// Calculate material utilization efficiency
const normalizedSpecs = $json;
const config = $('Set Workflow Configuration').item.json;
const historicalPricing = $('Fetch Historical Pricing').item.json;

// Helper function to parse dimensions string (e.g., "100x50x25mm" or "100 x 50 x 25")
function parseDimensions(dimensionString) {
  if (!dimensionString) return null;

  // Remove units and extra spaces
  const cleaned = dimensionString.toLowerCase()
    .replace(/mm|cm|m|inches|in/g, '')
    .trim();

  // Extract numbers using regex
  const numbers = cleaned.match(/[0-9.]+/g);

  if (!numbers || numbers.length < 3) return null;

  return {
    length: parseFloat(numbers[0]),
    width: parseFloat(numbers[1]),
    height: parseFloat(numbers[2])
  };
}

// Helper function to calculate volume in cubic millimeters
function calculateVolume(dimensions) {
  if (!dimensions) return 0;
  return dimensions.length * dimensions.width * dimensions.height;
}

// Parse dimensions from normalized specs
const dimensions = parseDimensions(normalizedSpecs.dimensions);

if (!dimensions) {
  return {
    error: 'Unable to parse dimensions',
    utilizationPercentage: 0,
    rawMaterialVolume: 0,
    finishedVolume: 0,
    estimatedMaterialCost: 0,
    wasteVolume: 0
  };
}

// Calculate finished part volume (in cubic mm)
const finishedVolume = calculateVolume(dimensions);

// Get waste percentage from config (default to 15% if not set)
const wastePercentage = config.materialWastePercent || 15;

// Calculate raw material volume needed (including waste)
const rawMaterialVolume = finishedVolume * (1 + wastePercentage / 100);

// Calculate waste volume
const wasteVolume = rawMaterialVolume - finishedVolume;

// Calculate utilization percentage
const utilizationPercentage = (finishedVolume / rawMaterialVolume) * 100;

// Estimate material cost based on volume and historical pricing
// Convert volume from cubic mm to cubic cm for pricing (1 cm³ = 1000 mm³)
const volumeInCubicCm = rawMaterialVolume / 1000;

// Get material price per cubic cm from historical data (default to $0.50/cm³ if not available)
const materialCode = normalizedSpecs.materialCode || 'unknown';
const pricePerCubicCm = historicalPricing?.materialPrices?.[materialCode] || 0.50;

// Calculate estimated material cost
const estimatedMaterialCost = volumeInCubicCm * pricePerCubicCm;

// Return utilization metrics
return {
  utilizationPercentage: Math.round(utilizationPercentage * 100) / 100,
  rawMaterialVolume: Math.round(rawMaterialVolume),
  finishedVolume: Math.round(finishedVolume),
  estimatedMaterialCost: Math.round(estimatedMaterialCost * 100) / 100,
  wasteVolume: Math.round(wasteVolume),
  wastePercentage: wastePercentage,
  dimensions: dimensions,
  materialCode: materialCode,
  pricePerCubicCm: pricePerCubicCm,
  volumeInCubicCm: Math.round(volumeInCubicCm * 100) / 100
};

