// Validate extraction quality from Claude Vision
const extractedData = $input.item.json;

// Define required fields
const requiredFields = ['material', 'dimensions', 'quantity'];
const optionalFields = ['tolerance', 'surfaceFinish', 'deliveryDate'];

// Check which required fields are present and valid
const missingFields = [];
const presentFields = [];

requiredFields.forEach(field => {
  const value = extractedData[field];
  if (!value || value === null || value === undefined || value === '') {
    missingFields.push(field);
  } else {
    presentFields.push(field);
  }
});

// Calculate field completeness percentage
const totalFields = requiredFields.length + optionalFields.length;
let completedFields = presentFields.length;

// Check optional fields
optionalFields.forEach(field => {
  const value = extractedData[field];
  if (value && value !== null && value !== undefined && value !== '') {
    completedFields++;
  }
});

const fieldCompletenessPercent = (completedFields / totalFields) * 100;

// Validate data types
const dataTypeValidation = {
  material: typeof extractedData.material === 'string',
  dimensions: typeof extractedData.dimensions === 'string' || typeof extractedData.dimensions === 'object',
  quantity: !isNaN(parseInt(extractedData.quantity))
};

const dataTypeValid = Object.values(dataTypeValidation).every(v => v === true);

// Extract AI confidence score if available (Claude may provide this in metadata)
const aiConfidence = extractedData.confidence || extractedData.confidence_score || 0.8; // default to 0.8 if not provided

// Calculate overall confidence score (0-1 scale)
// Weighted: 40% field completeness, 40% AI confidence, 20% data type validation
const fieldCompletenessScore = fieldCompletenessPercent / 100;
const dataTypeScore = dataTypeValid ? 1 : 0.5;
const overallConfidence = (
  (fieldCompletenessScore * 0.4) +
  (aiConfidence * 0.4) +
  (dataTypeScore * 0.2)
);

// Determine validation status
let validationStatus = 'passed';
if (missingFields.length > 0) {
  validationStatus = 'failed';
} else if (overallConfidence < 0.7) {
  validationStatus = 'needs_review';
}

// Return validation result
return {
  ...extractedData,
  validation: {
    status: validationStatus,
    confidenceScore: Math.round(overallConfidence * 100) / 100,
    fieldCompletenessPercent: Math.round(fieldCompletenessPercent * 100) / 100,
    missingFields: missingFields,
    presentFields: presentFields,
    dataTypeValidation: dataTypeValidation,
    dataTypeValid: dataTypeValid,
    aiConfidence: aiConfidence,
    requiresManualReview: validationStatus === 'needs_review' || validationStatus === 'failed'
  }
};

