// Generate comprehensive comparison matrix for all 3 suppliers
const costEstimates = $input.all();

// Helper function to calculate cost variance percentage
function calculateVariance(value, baseline) {
  if (!baseline || baseline === 0) return 0;
  return ((value - baseline) / baseline * 100).toFixed(2);
}

// Extract supplier data and organize by pricing tier
const suppliers = costEstimates.map(item => {
  const data = item.json;
  return {
    supplierId: data.supplier_id || data.supplierId,
    supplierName: data.supplier_name || data.supplierName,
    qualityScore: data.quality_score || data.qualityScore || 0,
    capacityAvailable: 100 - (data.current_capacity_percent || data.currentCapacityPercent || 0),
    avgLeadTimeDays: data.avg_lead_time_days || data.avgLeadTimeDays || 0,
    pricing: {
      competitive: {
        totalCost: data.competitiveCost || data.pricing?.competitive?.totalCost || 0,
        materialCost: data.competitiveMaterialCost || data.pricing?.competitive?.materialCost || 0,
        laborCost: data.competitiveLaborCost || data.pricing?.competitive?.laborCost || 0,
        overhead: data.competitiveOverhead || data.pricing?.competitive?.overhead || 0,
        margin: data.competitiveMargin || data.pricing?.competitive?.margin || 0,
        leadTime: data.competitiveLeadTime || data.pricing?.competitive?.leadTime || data.avgLeadTimeDays || 0
      },
      standard: {
        totalCost: data.standardCost || data.pricing?.standard?.totalCost || 0,
        materialCost: data.standardMaterialCost || data.pricing?.standard?.materialCost || 0,
        laborCost: data.standardLaborCost || data.pricing?.standard?.laborCost || 0,
        overhead: data.standardOverhead || data.pricing?.standard?.overhead || 0,
        margin: data.standardMargin || data.pricing?.standard?.margin || 0,
        leadTime: data.standardLeadTime || data.pricing?.standard?.leadTime || data.avgLeadTimeDays || 0
      },
      premium: {
        totalCost: data.premiumCost || data.pricing?.premium?.totalCost || 0,
        materialCost: data.premiumMaterialCost || data.pricing?.premium?.materialCost || 0,
        laborCost: data.premiumLaborCost || data.pricing?.premium?.laborCost || 0,
        overhead: data.premiumOverhead || data.pricing?.premium?.overhead || 0,
        margin: data.premiumMargin || data.pricing?.premium?.margin || 0,
        leadTime: data.premiumLeadTime || data.pricing?.premium?.leadTime || Math.floor((data.avgLeadTimeDays || 0) * 0.7) || 0
      }
    },
    totalScore: data.totalScore || data.scores?.total || 0
  };
});

// Find baseline (lowest cost) for variance calculations
const allCompetitiveCosts = suppliers.map(s => s.pricing.competitive.totalCost).filter(c => c > 0);
const baselineCost = Math.min(...allCompetitiveCosts);

// Create comparison matrix
const comparisonMatrix = {
  suppliers: suppliers.map(supplier => ({
    id: supplier.supplierId,
    name: supplier.supplierName,
    qualityScore: supplier.qualityScore,
    capacityAvailable: `${supplier.capacityAvailable.toFixed(1)}%`,
    totalScore: supplier.totalScore,
    pricingTiers: {
      competitive: {
        totalCost: supplier.pricing.competitive.totalCost,
        breakdown: {
          material: supplier.pricing.competitive.materialCost,
          labor: supplier.pricing.competitive.laborCost,
          overhead: supplier.pricing.competitive.overhead,
          margin: supplier.pricing.competitive.margin
        },
        leadTimeDays: supplier.pricing.competitive.leadTime,
        costVariance: `${calculateVariance(supplier.pricing.competitive.totalCost, baselineCost)}%`
      },
      standard: {
        totalCost: supplier.pricing.standard.totalCost,
        breakdown: {
          material: supplier.pricing.standard.materialCost,
          labor: supplier.pricing.standard.laborCost,
          overhead: supplier.pricing.standard.overhead,
          margin: supplier.pricing.standard.margin
        },
        leadTimeDays: supplier.pricing.standard.leadTime,
        costVariance: `${calculateVariance(supplier.pricing.standard.totalCost, baselineCost)}%`
      },
      premium: {
        totalCost: supplier.pricing.premium.totalCost,
        breakdown: {
          material: supplier.pricing.premium.materialCost,
          labor: supplier.pricing.premium.laborCost,
          overhead: supplier.pricing.premium.overhead,
          margin: supplier.pricing.premium.margin
        },
        leadTimeDays: supplier.pricing.premium.leadTime,
        costVariance: `${calculateVariance(supplier.pricing.premium.totalCost, baselineCost)}%`
      }
    }
  })),
  summary: {
    lowestCompetitiveCost: Math.min(...suppliers.map(s => s.pricing.competitive.totalCost)),
    lowestStandardCost: Math.min(...suppliers.map(s => s.pricing.standard.totalCost)),
    lowestPremiumCost: Math.min(...suppliers.map(s => s.pricing.premium.totalCost)),
    fastestLeadTime: Math.min(...suppliers.map(s => s.pricing.premium.leadTime)),
    highestQualityScore: Math.max(...suppliers.map(s => s.qualityScore)),
    avgCostVariance: suppliers.reduce((sum, s) => sum + parseFloat(calculateVariance(s.pricing.standard.totalCost, baselineCost)), 0) / suppliers.length
  }
};

// Determine best value option
const bestValueScores = suppliers.map(supplier => {
  // Calculate value score: balance of cost, quality, and lead time
  const costScore = 100 - parseFloat(calculateVariance(supplier.pricing.standard.totalCost, baselineCost));
  const qualityScore = supplier.qualityScore;
  const leadTimeScore = supplier.pricing.standard.leadTime > 0 
    ? 100 - (supplier.pricing.standard.leadTime / Math.max(...suppliers.map(s => s.pricing.standard.leadTime)) * 100)
    : 0;
  const capacityScore = supplier.capacityAvailable;

  const valueScore = (costScore * 0.4) + (qualityScore * 0.3) + (leadTimeScore * 0.2) + (capacityScore * 0.1);

  return {
    supplierId: supplier.supplierId,
    supplierName: supplier.supplierName,
    valueScore: valueScore.toFixed(2),
    tier: 'standard'
  };
});

const bestValue = bestValueScores.reduce((best, current) => 
  parseFloat(current.valueScore) > parseFloat(best.valueScore) ? current : best
);

// Add recommendations
const recommendations = {
  bestValue: {
    supplier: bestValue.supplierName,
    supplierId: bestValue.supplierId,
    tier: bestValue.tier,
    reason: `Best overall value with score of ${bestValue.valueScore} based on cost, quality, lead time, and capacity`
  },
  lowestCost: {
    supplier: suppliers.find(s => s.pricing.competitive.totalCost === comparisonMatrix.summary.lowestCompetitiveCost)?.supplierName,
    tier: 'competitive',
    cost: comparisonMatrix.summary.lowestCompetitiveCost
  },
  fastestDelivery: {
    supplier: suppliers.find(s => s.pricing.premium.leadTime === comparisonMatrix.summary.fastestLeadTime)?.supplierName,
    tier: 'premium',
    leadTimeDays: comparisonMatrix.summary.fastestLeadTime
  },
  highestQuality: {
    supplier: suppliers.find(s => s.qualityScore === comparisonMatrix.summary.highestQualityScore)?.supplierName,
    qualityScore: comparisonMatrix.summary.highestQualityScore
  }
};

// Return formatted comparison matrix with recommendations
